const colors=[{name:'Milk',ru:'Молочный',hex:'#eee7d8',ink:'#292d2a'},{name:'Denim blue',ru:'Джинсовый синий',hex:'#477a9c',ink:'#f4eddc'},{name:'Sand honey',ru:'Песочно-медовый',hex:'#d8ac66',ink:'#292d2a'},{name:'Ice blue',ru:'Ледяной голубой',hex:'#b9d4e1',ink:'#292d2a'},{name:'Muted wine',ru:'Приглушённый винный',hex:'#753644',ink:'#f5e9d3'},{name:'Graphite',ru:'Графит',hex:'#3d4142',ink:'#f4eddc'}];
const cases=[{name:'Silver aluminum',hex:'#b8bdbb'},{name:'Ivory',hex:'#d9d2bf'},{name:'Deep blue',hex:'#253b53'},{name:'Black',hex:'#252725'}];let selectedCase=1,selectedKey=1;
function board(ci,ki,id='kb'){const c=cases[ci],k=colors[ki];let out=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 378"><defs><linearGradient id="${id}case" x2="0" y2="1"><stop stop-color="${c.hex}"/><stop offset="1" stop-color="${c.hex}" stop-opacity=".8"/></linearGradient><linearGradient id="${id}key" x2="0" y2="1"><stop stop-color="#fff" stop-opacity=".16"/><stop offset=".55" stop-color="#fff" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity=".18"/></linearGradient><filter id="${id}s"><feDropShadow dx="0" dy="3" stdDeviation="1.6" flood-opacity=".55"/></filter></defs><rect x="5" y="12" width="890" height="356" rx="24" fill="${c.hex}"/><rect x="5" y="5" width="890" height="348" rx="24" fill="url(#${id}case)" stroke="#ffffff55" stroke-width="2"/><rect x="22" y="24" width="802" height="311" rx="9" fill="#171d1b"/>`;
const rows=[['Esc','F1','F2','F3','F4','F5','F6','F7','F8','F9','F10','F11','F12','Del'],['~ Ё','1 !','2 @','3 #','4 $','5 %','6 ^','7 &','8 *','9 (','0 )','− _','= +','Backspace'],['Tab','Q Й','W Ц','E У','R К','T Е','Y Н','U Г','I Ш','O Щ','P З','[ Х','] Ъ','\\'],['Caps','A Ф','S Ы','D В','F А','G П','H Р','J О','K Л','L Д','; Ж',"’ Э",'Enter'],['Shift','Z Я','X Ч','C С','V М','B И','N Т','M Ь',', Б','. Ю','/ ?','Shift'],['Ctrl','Win','Alt','SPACE','Alt','Fn','Ctrl']];
const ys=[28,82,132,182,232,282];for(let r=0;r<rows.length;r++){let x=27;const widths=rows[r].map((v,i)=>r===0?51:r===1?(i===13?100:48):r===2?(i===0?70:i===13?78:48):r===3?(i===0?83:i===12?117:48):r===4?(i===0?107:i===11?145:48):(v==='SPACE'?300:61));rows[r].forEach((v,i)=>{let w=widths[i],y=ys[r],h=r===0?43:44;out+=`<g filter="url(#${id}s)"><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="6" fill="${k.hex}"/><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="6" fill="url(#${id}key)" stroke="#ffffff22"/></g>`;if(v==='SPACE'){out+=`<path d="M${x+10} ${y+34} C${x+75} ${y+10},${x+100} ${y+48},${x+w-50} ${y+13} C${x+w+4} ${y-2},${x+w+7} ${y+38},${x+w-20} ${y+37} Z" fill="${k.ink}"/><ellipse cx="${x+w-34}" cy="${y+23}" rx="12" ry="5" fill="${k.hex}"/>`;}else{const a=v.split(' ');out+=`<text x="${x+8}" y="${y+16}" font-family="Arial,sans-serif" font-size="${v.length>5?9:11}" font-weight="600" fill="${k.ink}">${a[0].replace('&','&amp;').replace('<','&lt;')}</text>`;if(a[1])out+=`<text x="${x+29}" y="${y+33}" font-family="Arial,sans-serif" font-size="10" fill="${k.ink}">${a[1].replace('&','&amp;')}</text>`;if(['Esc','Enter','Shift','Tab','Del'].includes(v))out+=`<path d="M${x+w-31} ${y+h-8} Q${x+w-4} ${y+h-7} ${x+w-6} ${y+19} Q${x+w-17} ${y+h-9} ${x+w-31} ${y+h-8}" fill="${k.ink}"/>`;}x+=w+5;});}
out+=`<circle cx="854" cy="49" r="25" fill="#101412"/><circle cx="854" cy="45" r="24" fill="#252a26" stroke="#55594e"/>`;['Home','PgUp','PgDn','↑','↓'].forEach((v,i)=>{out+=`<rect x="834" y="${88+i*49}" width="42" height="43" rx="5" fill="${k.hex}" stroke="#0004"/><text x="855" y="${111+i*49}" text-anchor="middle" font-size="10" fill="${k.ink}" font-family="Arial">${v}</text>`;});out+=`<path d="M438 344 Q451 345 463 337 Q461 347 446 348Z" fill="#4b5149"/></svg>`;return out;}
document.querySelector('#hero-board').innerHTML=board(1,1,'hero');document.querySelector('#color-cards').innerHTML=colors.slice(0,3).map((c,i)=>`<button class="card" data-key="${i}" aria-label="Configure ${c.name} keycaps"><div class="card-top"><span>0${i+1} / ${c.ru.toUpperCase()}</span><span>EN + RU</span></div>${board(1,i,'card'+i)}<div class="card-bottom"><strong>${c.name}</strong><span>↗</span></div></button>`).join('');
function render(){document.querySelector('#config-board').innerHTML=board(selectedCase,selectedKey,'config');document.querySelector('#config-board').setAttribute('aria-label',`${cases[selectedCase].name} case with ${colors[selectedKey].name} keycaps, illustrated preview`);document.querySelector('#case-name').textContent=cases[selectedCase].name;document.querySelector('#key-name').textContent=colors[selectedKey].name;document.querySelector('#combo-caption').textContent=`${cases[selectedCase].name.toUpperCase()} / ${colors[selectedKey].name.toUpperCase()}`;for(const [group,items,sel] of [['cases',cases,selectedCase],['keys',colors,selectedKey]])document.querySelector('#'+group).innerHTML=items.map((c,i)=>`<button class="swatch" style="background:${c.hex}" aria-label="${c.name}" title="${c.name}" aria-pressed="${sel===i}" data-group="${group}" data-index="${i}"></button>`).join('');}
document.addEventListener('click',e=>{const sw=e.target.closest('.swatch');if(sw){if(sw.dataset.group==='cases')selectedCase=Number(sw.dataset.index);else selectedKey=Number(sw.dataset.index);render();history.replaceState(null,'',`?case=${selectedCase}&color=${selectedKey}#configure`);document.querySelector('#status').textContent='';}const card=e.target.closest('.card');if(card){selectedKey=Number(card.dataset.key);render();document.querySelector('#configure').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}});
const params=new URLSearchParams(location.search);const savedCase=Number(params.get('case')),savedKey=Number(params.get('color'));if(Number.isInteger(savedCase)&&savedCase>=0&&savedCase<cases.length)selectedCase=params.has('case')?savedCase:1;if(Number.isInteger(savedKey)&&savedKey>=0&&savedKey<colors.length)selectedKey=params.has('color')?savedKey:1;render();
document.querySelector('#save-build').addEventListener('click',()=>{const svg=board(selectedCase,selectedKey,'saved').replace('viewBox="0 0 900 378"','viewBox="0 0 900 510"').replace('</svg>',`<text x="28" y="420" font-family="Arial" font-size="25" fill="#252c29">FORM / ${cases[selectedCase].name} + ${colors[selectedKey].name}</text><text x="28" y="451" font-family="Arial" font-size="14" fill="#60685c">English + Russian · Character collection · Illustrated concept</text><text x="28" y="480" font-family="Arial" font-size="12" fill="#60685c">Availability and pricing to be confirmed.</text></svg>`);const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));const a=document.createElement('a');a.href=url;a.download=`form-${cases[selectedCase].name.toLowerCase().replaceAll(' ','-')}-${colors[selectedKey].name.toLowerCase().replaceAll(' ','-')}.svg`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#status').textContent='Your build card has been downloaded.';});
